	public EvidenceStateRef internPayload(
			FrontierStateKey key,
			EvidenceStateSummary summary,
			FrontierStateOperation operation,
			EvidenceStateRef firstParent,
			EvidenceStateRef secondParent,
			int operationRecipeId,
			FrontierPayloadWriter writer) {
		ensureOpen();
		Objects.requireNonNull(key, "key");
		Objects.requireNonNull(summary, "summary");
		Objects.requireNonNull(operation, "operation");
		Objects.requireNonNull(writer, "writer");
		if (writer.arena() != this || !writer.key().equals(key)) {
			throw new IllegalArgumentException("payload writer belongs to another arena or canonical key");
		}
		try {
			if (!canonicalUniverseSealed || canonicalStateId(key) == 0) {
				throw new IllegalStateException("payload states require a predeclared canonical key");
			}
			if (!summary.guarantee().isComposablePointEstimate()) {
				throw new IllegalArgumentException("only composable evidence may carry a frontier payload");
			}
			if (operation == FrontierStateOperation.SUMMARY_ONLY
					|| operation == FrontierStateOperation.UNRESOLVED) {
				throw new IllegalArgumentException("non-replayable operations cannot carry a frontier payload");
			}
			validateExactPayloadOperation(operation, summary);
			validateProvenance(key, operation, firstParent, secondParent, operationRecipeId);
			FrontierPayloadBlock block = writer.finish();
			validatePayloadSummary(summary, block);
			validateInheritedRandomMass(operation, firstParent, secondParent, block);
			int firstParentStateId = stateId(firstParent);
			int secondParentStateId = stateId(secondParent);
			int existingStateId = payloadDerivationStateId(
					key, operation, firstParentStateId, secondParentStateId, operationRecipeId);
			if (existingStateId != 0) {
				validateExistingPayload(
						existingStateId,
						summary,
						operation,
						firstParent,
						secondParent,
						operationRecipeId,
						block);
				writer.close();
				return references[existingStateId];
			}

			int canonicalStateId = canonicalStateId(key);
			if (materialized[canonicalStateId]) {
				return materializeDerivedPayload(
						key, summary, operation, firstParent, secondParent, operationRecipeId, writer, block);
			}
			int sharedPayloadOwnerStateId = payloadContentOwnerStateId(key, block);
			if (sharedPayloadOwnerStateId != 0) {
				writer.close();
				return materializeCanonicalSharedPayload(
						key, summary, operation, firstParentStateId, secondParentStateId,
						operationRecipeId, sharedPayloadOwnerStateId);
			}

			ensurePayloadDerivationCapacity(payloadDerivationCount + 1);
			ensurePayloadContentCapacity(payloadContentCount + 1);
			EvidenceStateRef reference = intern(key, summary);
			int stateId = reference.stateId();
			long payloadBytes = block.retainedBytes;
			long digestHigh = block.digestHigh();
			long digestLow = block.digestLow();
			writer.transferToResident();
			operations[stateId] = (byte) operation.ordinal();
			firstParentStateIds[stateId] = firstParentStateId;
			secondParentStateIds[stateId] = secondParentStateId;
			operationRecipeIds[stateId] = operationRecipeId;
			payloadOwnerStateIds[stateId] = stateId;
			payloadBlocks[stateId] = block;
			exactAtomCounts[stateId] = block.exactCount();
			residualParticleCounts[stateId] = block.residualCount();
			payloadBytesByState[stateId] = payloadBytes;
			payloadDigestHigh[stateId] = digestHigh;
			payloadDigestLow[stateId] = digestLow;
			payloadStatuses[stateId] = (byte) FrontierPayloadStatus.RESIDENT.ordinal();
			dispositions[stateId] = (byte) FrontierStateDisposition.COMPOSABLE_PAYLOAD.ordinal();
			indexPayloadDerivation(stateId);
			indexPayloadContentOwner(stateId);
			return reference;
		} catch (RuntimeException | Error failure) {
			writer.close();
			throw failure;
		}
	}

	/** Returns whether an unscaled raw composable payload can be detached without retaining this arena. */
	public boolean isDetachablePayload(EvidenceStateRef reference) {
		int stateId = validate(reference);
		int payloadStateId = payloadStateId(stateId);
		return keys[stateId] != null
				&& reference.summary().guarantee().isComposablePointEstimate()
				&& dispositions[stateId] == (byte) FrontierStateDisposition.COMPOSABLE_PAYLOAD.ordinal()
				&& keys[stateId].equals(keys[payloadStateId])
				&& payloadStatuses[payloadStateId] == (byte) FrontierPayloadStatus.RESIDENT.ordinal()
				&& cumulativeWeightScales[stateId] == 1.0d
				&& nearestCalibration(stateId) == null;
	}

	/**
	 * Detaches one immutable raw payload, including residual particles and its statistical summary.
	 */
	public FrontierPayloadSnapshot snapshotPayload(EvidenceStateRef reference) {
		int stateId = validate(reference);
		if (!isDetachablePayload(reference)) {
			throw new IllegalArgumentException(
					"only a resident unscaled calibration-free composable payload can be snapshotted");
		}
		FrontierPayloadBlock block = payloadBlocks[payloadStateId(stateId)];
		if (block == null) {
			throw new IllegalStateException("frontier state has no resident payload");
		}
		return FrontierPayloadSnapshot.of(keys[stateId], reference.summary(), block);
	}

	/**
	 * Detaches one immutable database-exact payload without retaining this arena or its query-local layout names.
	 */
	public FrontierExactPayloadSnapshot snapshotExactPayload(EvidenceStateRef reference) {
		int stateId = validate(reference);
		int payloadStateId = payloadStateId(stateId);
		if (keys[stateId] == null
				|| reference.summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT
				|| dispositions[stateId] != (byte) FrontierStateDisposition.COMPOSABLE_PAYLOAD.ordinal()
				|| canonicalStateId(keys[stateId]) != stateId
				|| !keys[stateId].equals(keys[payloadStateId])
				|| payloadStatuses[payloadStateId] != (byte) FrontierPayloadStatus.RESIDENT.ordinal()
				|| cumulativeWeightScales[stateId] != 1.0d) {
			throw new IllegalArgumentException("only a resident canonical database-exact payload can be snapshotted");
		}
		FrontierPayloadBlock block = payloadBlocks[payloadStateId];
		if (block == null || block.residualCount() != 0) {
			throw new IllegalStateException("database-exact frontier state has no exact resident payload");
		}
		return FrontierExactPayloadSnapshot.of(keys[stateId], block);
	}

	/**
	 * Rebinds a detached exact payload into the current canonical state universe and current operation provenance.
	 */
	public EvidenceStateRef internExactPayloadSnapshot(
			FrontierStateKey key,
			FrontierStateOperation operation,
			EvidenceStateRef firstParent,
			EvidenceStateRef secondParent,
			int operationRecipeId,
			FrontierExactPayloadSnapshot snapshot) {
		ensureOpen();
		Objects.requireNonNull(key, "key");
		Objects.requireNonNull(operation, "operation");
		Objects.requireNonNull(snapshot, "snapshot");
		if (!canonicalUniverseSealed || canonicalStateId(key) == 0) {
			throw new IllegalStateException("payload snapshots require a predeclared canonical key");
		}
		if (operation == FrontierStateOperation.SUMMARY_ONLY
				|| operation == FrontierStateOperation.UNRESOLVED
				|| operation == FrontierStateOperation.CALIBRATE) {
			throw new IllegalArgumentException("operation cannot attach an exact payload snapshot");
		}
		if (!snapshot.matches(key)) {
			throw new IllegalArgumentException("exact payload snapshot identity or slot shape does not match the key");
		}
		validateProvenance(key, operation, firstParent, secondParent, operationRecipeId);
		EvidenceStateSummary summary = EvidenceStateSummary.exact(snapshot.rows());
		FrontierPayloadBlock block = FrontierPayloadBlock.rebound(key.maskStrata(), snapshot);
		validatePayloadSummary(summary, block);
		validateInheritedRandomMass(operation, firstParent, secondParent, block);
		int existingStateId = payloadDerivationStateId(
				key, operation, stateId(firstParent), stateId(secondParent), operationRecipeId);
		if (existingStateId != 0) {
			validateExistingPayload(existingStateId, summary, operation, firstParent, secondParent,
					operationRecipeId, block);
			return references[existingStateId];
		}

		try (FrontierMemoryReservation reservation = reserveTemporary(
				snapshot.logicalPayloadBytes(), FrontierMemoryPurpose.REMATERIALIZATION)) {
			if (materialized[canonicalStateId(key)]) {
				return materializeDerivedSnapshotPayload(
						key, summary, operation, firstParent, secondParent, operationRecipeId, block, reservation);
			}
			int sharedPayloadOwnerStateId = payloadContentOwnerStateId(key, block);
			if (sharedPayloadOwnerStateId != 0) {
				return materializeCanonicalSharedPayload(
						key, summary, operation, stateId(firstParent), stateId(secondParent),
						operationRecipeId, sharedPayloadOwnerStateId);
			}
			ensurePayloadDerivationCapacity(payloadDerivationCount + 1);
			ensurePayloadContentCapacity(payloadContentCount + 1);
			EvidenceStateRef reference = intern(key, summary);
			int stateId = reference.stateId();
			operations[stateId] = (byte) operation.ordinal();
			firstParentStateIds[stateId] = stateId(firstParent);
			secondParentStateIds[stateId] = stateId(secondParent);
			operationRecipeIds[stateId] = operationRecipeId;
			payloadOwnerStateIds[stateId] = stateId;
			payloadBlocks[stateId] = block;
			exactAtomCounts[stateId] = block.exactCount();
			residualParticleCounts[stateId] = 0;
			payloadBytesByState[stateId] = block.retainedBytes;
			payloadDigestHigh[stateId] = block.digestHigh();
			payloadDigestLow[stateId] = block.digestLow();
			payloadStatuses[stateId] = (byte) FrontierPayloadStatus.RESIDENT.ordinal();
			dispositions[stateId] = (byte) FrontierStateDisposition.COMPOSABLE_PAYLOAD.ordinal();
			reservation.transferToResident(block.retainedBytes);
			indexPayloadDerivation(stateId);
			indexPayloadContentOwner(stateId);
			return reference;
		}
	}

	/**
	 * Rebinds a detached composable payload into the current canonical state universe and current operation provenance.
	 */
	public EvidenceStateRef internPayloadSnapshot(
			FrontierStateKey key,
			FrontierStateOperation operation,
			EvidenceStateRef firstParent,
			EvidenceStateRef secondParent,
			int operationRecipeId,
			FrontierPayloadSnapshot snapshot) {
		ensureOpen();
		Objects.requireNonNull(key, "key");
		Objects.requireNonNull(operation, "operation");
		Objects.requireNonNull(snapshot, "snapshot");
		if (!canonicalUniverseSealed || canonicalStateId(key) == 0) {
			throw new IllegalStateException("payload snapshots require a predeclared canonical key");
		}
		if (operation == FrontierStateOperation.SUMMARY_ONLY
				|| operation == FrontierStateOperation.UNRESOLVED
				|| operation == FrontierStateOperation.CALIBRATE) {
			throw new IllegalArgumentException("operation cannot attach a payload snapshot");
		}
		if (!snapshot.matches(key)) {
			throw new IllegalArgumentException("payload snapshot identity or slot shape does not match the key");
		}
		EvidenceStateSummary summary = snapshot.summary();
		if (!summary.guarantee().isComposablePointEstimate()) {
			throw new IllegalArgumentException("payload snapshot evidence is not composable");
		}
		validateExactPayloadOperation(operation, summary);
		validateProvenance(key, operation, firstParent, secondParent, operationRecipeId);
		FrontierPayloadBlock block = FrontierPayloadBlock.rebound(key.maskStrata(), snapshot);
		validatePayloadSummary(summary, block);
		validateInheritedRandomMass(operation, firstParent, secondParent, block);
		int existingStateId = payloadDerivationStateId(
				key, operation, stateId(firstParent), stateId(secondParent), operationRecipeId);
		if (existingStateId != 0) {
			validateExistingPayload(existingStateId, summary, operation, firstParent, secondParent,
					operationRecipeId, block);
			return references[existingStateId];
		}

		try (FrontierMemoryReservation reservation = reserveTemporary(
				snapshot.logicalPayloadBytes(), FrontierMemoryPurpose.REMATERIALIZATION)) {
			if (materialized[canonicalStateId(key)]) {
				return materializeDerivedSnapshotPayload(
						key, summary, operation, firstParent, secondParent, operationRecipeId, block, reservation);
			}
			int sharedPayloadOwnerStateId = payloadContentOwnerStateId(key, block);
			if (sharedPayloadOwnerStateId != 0) {
				return materializeCanonicalSharedPayload(
						key, summary, operation, stateId(firstParent), stateId(secondParent),
						operationRecipeId, sharedPayloadOwnerStateId);
			}
			ensurePayloadDerivationCapacity(payloadDerivationCount + 1);
			ensurePayloadContentCapacity(payloadContentCount + 1);
			EvidenceStateRef reference = intern(key, summary);
			int stateId = reference.stateId();
			operations[stateId] = (byte) operation.ordinal();
			firstParentStateIds[stateId] = stateId(firstParent);
			secondParentStateIds[stateId] = stateId(secondParent);
			operationRecipeIds[stateId] = operationRecipeId;
			payloadOwnerStateIds[stateId] = stateId;
			payloadBlocks[stateId] = block;
			exactAtomCounts[stateId] = block.exactCount();
			residualParticleCounts[stateId] = block.residualCount();
			payloadBytesByState[stateId] = block.retainedBytes;
			payloadDigestHigh[stateId] = block.digestHigh();
			payloadDigestLow[stateId] = block.digestLow();
			payloadStatuses[stateId] = (byte) FrontierPayloadStatus.RESIDENT.ordinal();
			dispositions[stateId] = (byte) FrontierStateDisposition.COMPOSABLE_PAYLOAD.ordinal();
			reservation.transferToResident(block.retainedBytes);
			indexPayloadDerivation(stateId);
			indexPayloadContentOwner(stateId);
			return reference;
		}
	}

	private EvidenceStateRef materializeDerivedSnapshotPayload(
			FrontierStateKey key,
			EvidenceStateSummary summary,
			FrontierStateOperation operation,
			EvidenceStateRef firstParent,
			EvidenceStateRef secondParent,
			int operationRecipeId,
			FrontierPayloadBlock block,
			FrontierMemoryReservation reservation) {
		if (operation == FrontierStateOperation.EXACT_LEAF) {
			throw new IllegalStateException("one canonical database-exact leaf must define each logical leaf state");
		}
		int firstParentStateId = stateId(firstParent);
		int secondParentStateId = stateId(secondParent);
		int existingStateId = payloadDerivationStateId(
				key, operation, firstParentStateId, secondParentStateId, operationRecipeId);
		if (existingStateId != 0) {
			validateExistingPayload(existingStateId, summary, operation, firstParent, secondParent,
					operationRecipeId, block);
			return references[existingStateId];
		}
		int sharedPayloadOwnerStateId = payloadContentOwnerStateId(key, block);
		if (sharedPayloadOwnerStateId != 0) {
			return materializeSharedPayload(
					key, summary, operation, firstParentStateId, secondParentStateId,
					operationRecipeId, sharedPayloadOwnerStateId);
		}

		ensurePayloadDerivationCapacity(payloadDerivationCount + 1);
		ensurePayloadContentCapacity(payloadContentCount + 1);
		int stateId = highWaterStateId + 1;
		ensureCapacity(stateId);
		long retainedBytes = summaryRetainedBytes(summary);
		reservePersistent(retainedBytes);
		EvidenceStateRef reference = materializeState(
				stateId, key, key.frontier(), summary, key.deterministicSeed());
		operations[stateId] = (byte) operation.ordinal();
		firstParentStateIds[stateId] = firstParentStateId;
		secondParentStateIds[stateId] = secondParentStateId;
		operationRecipeIds[stateId] = operationRecipeId;
		payloadOwnerStateIds[stateId] = stateId;
		payloadBlocks[stateId] = block;
		exactAtomCounts[stateId] = block.exactCount();
		residualParticleCounts[stateId] = block.residualCount();
		payloadBytesByState[stateId] = block.retainedBytes;
		payloadDigestHigh[stateId] = block.digestHigh();
		payloadDigestLow[stateId] = block.digestLow();
		payloadStatuses[stateId] = (byte) FrontierPayloadStatus.RESIDENT.ordinal();
		dispositions[stateId] = (byte) FrontierStateDisposition.COMPOSABLE_PAYLOAD.ordinal();
		reservation.transferToResident(block.retainedBytes);
		allocatedBytes += retainedBytes;
		updatePeak();
		highWaterStateId = stateId;
		indexPayloadDerivation(stateId);
		indexPayloadContentOwner(stateId);
		return reference;
	}

	/**
	 * Materializes a lineage-specific payload without occupying the canonical slot for {@code key}.
	 *
	 * <p>
	 * The same logical factor set may be reached through different physical alternatives or through one or more learned
	 * calibration overlays. Those derivations intentionally retain distinct states, summaries, and provenance. The
	 * declared canonical key and its deterministic seed are shared; byte-identical sealed payload blocks may also share
	 * storage after their complete content has been verified.
	 */
	public EvidenceStateRef derivePayload(
			FrontierStateKey key,
			EvidenceStateSummary summary,
			FrontierStateOperation operation,
			EvidenceStateRef firstParent,
			EvidenceStateRef secondParent,
			int operationRecipeId,
			FrontierPayloadWriter writer) {
		ensureOpen();
		Objects.requireNonNull(key, "key");
		Objects.requireNonNull(summary, "summary");
		Objects.requireNonNull(operation, "operation");
		Objects.requireNonNull(writer, "writer");
		int canonicalStateId = canonicalStateId(key);
		if (!canonicalUniverseSealed || canonicalStateId == 0) {
			throw new IllegalStateException("derived payload states require a predeclared canonical key");
		}
		FrontierStateKey declaredKey = keys[canonicalStateId];
		if (writer.arena() != this || !declaredKey.equals(writer.key())) {
			throw new IllegalArgumentException("payload writer belongs to another arena or canonical key");
		}
		if (!summary.guarantee().isComposablePointEstimate()) {
			throw new IllegalArgumentException("only composable evidence may carry a frontier payload");
		}
		if (operation == FrontierStateOperation.SUMMARY_ONLY
				|| operation == FrontierStateOperation.UNRESOLVED
				|| operation == FrontierStateOperation.CALIBRATE) {
			throw new IllegalArgumentException("operation cannot materialize a derived payload");
		}
		if (operation == FrontierStateOperation.EXACT_LEAF) {
			throw new IllegalArgumentException("database-exact leaves must occupy their canonical state");
		}
		validateExactPayloadOperation(operation, summary);
		validateProvenance(declaredKey, operation, firstParent, secondParent, operationRecipeId);
		try {
			FrontierPayloadBlock block = writer.finish();
			validatePayloadSummary(summary, block);
			validateInheritedRandomMass(operation, firstParent, secondParent, block);
			return materializeDerivedPayload(
					declaredKey, summary, operation, firstParent, secondParent, operationRecipeId, writer, block);
		} catch (RuntimeException | Error failure) {
			writer.close();
			throw failure;
		}
	}

	private EvidenceStateRef materializeDerivedPayload(
			FrontierStateKey key,
			EvidenceStateSummary summary,
			FrontierStateOperation operation,
			EvidenceStateRef firstParent,
			EvidenceStateRef secondParent,
			int operationRecipeId,
			FrontierPayloadWriter writer,
			FrontierPayloadBlock block) {
		if (operation == FrontierStateOperation.EXACT_LEAF) {
			throw new IllegalStateException("one canonical database-exact leaf must define each logical leaf state");
		}
		int firstParentStateId = stateId(firstParent);
		int secondParentStateId = stateId(secondParent);
		int existingStateId = payloadDerivationStateId(
				key, operation, firstParentStateId, secondParentStateId, operationRecipeId);
		if (existingStateId != 0) {
			validateExistingPayload(existingStateId, summary, operation, firstParent, secondParent,
					operationRecipeId, block);
			writer.close();
			return references[existingStateId];
		}
		int sharedPayloadOwnerStateId = payloadContentOwnerStateId(key, block);
		if (sharedPayloadOwnerStateId != 0) {
			writer.close();
			return materializeSharedPayload(
					key, summary, operation, firstParentStateId, secondParentStateId,
					operationRecipeId, sharedPayloadOwnerStateId);
		}

		ensurePayloadDerivationCapacity(payloadDerivationCount + 1);
		ensurePayloadContentCapacity(payloadContentCount + 1);
		int stateId = highWaterStateId + 1;
		ensureCapacity(stateId);
		long retainedBytes = summaryRetainedBytes(summary);
		reservePersistent(retainedBytes);
		EvidenceStateRef reference = materializeState(
				stateId,
				key,
				key.frontier(),
				summary,
				key.deterministicSeed());
		operations[stateId] = (byte) operation.ordinal();
		firstParentStateIds[stateId] = firstParentStateId;
		secondParentStateIds[stateId] = secondParentStateId;
		operationRecipeIds[stateId] = operationRecipeId;
		payloadOwnerStateIds[stateId] = stateId;
		payloadBlocks[stateId] = block;
		exactAtomCounts[stateId] = block.exactCount();
		residualParticleCounts[stateId] = block.residualCount();
		payloadBytesByState[stateId] = block.retainedBytes;
		payloadDigestHigh[stateId] = block.digestHigh();
		payloadDigestLow[stateId] = block.digestLow();
		payloadStatuses[stateId] = (byte) FrontierPayloadStatus.RESIDENT.ordinal();
		dispositions[stateId] = (byte) FrontierStateDisposition.COMPOSABLE_PAYLOAD.ordinal();
		writer.transferToResident();
		allocatedBytes += retainedBytes;
		updatePeak();
		highWaterStateId = stateId;
		indexPayloadDerivation(stateId);
		indexPayloadContentOwner(stateId);
		return reference;
	}

	private EvidenceStateRef materializeSharedPayload(
			FrontierStateKey key,
			EvidenceStateSummary summary,
			FrontierStateOperation operation,
			int firstParentStateId,
			int secondParentStateId,
			int operationRecipeId,
			int payloadOwnerStateId) {
		ensurePayloadDerivationCapacity(payloadDerivationCount + 1);
		int stateId = highWaterStateId + 1;
		ensureCapacity(stateId);
		long retainedBytes = summaryRetainedBytes(summary);
		reservePersistent(retainedBytes);
		EvidenceStateRef reference = materializeState(
				stateId, key, key.frontier(), summary, key.deterministicSeed());
		operations[stateId] = (byte) operation.ordinal();
		firstParentStateIds[stateId] = firstParentStateId;
		secondParentStateIds[stateId] = secondParentStateId;
		operationRecipeIds[stateId] = operationRecipeId;
		payloadOwnerStateIds[stateId] = payloadOwnerStateId;
		dispositions[stateId] = (byte) FrontierStateDisposition.COMPOSABLE_PAYLOAD.ordinal();
		allocatedBytes += retainedBytes;
		updatePeak();
		highWaterStateId = stateId;
		indexPayloadDerivation(stateId);
		return reference;
	}

	private EvidenceStateRef materializeCanonicalSharedPayload(
			FrontierStateKey key,
			EvidenceStateSummary summary,
			FrontierStateOperation operation,
			int firstParentStateId,
			int secondParentStateId,
			int operationRecipeId,
			int payloadOwnerStateId) {
		ensurePayloadDerivationCapacity(payloadDerivationCount + 1);
		EvidenceStateRef reference = intern(key, summary);
		int stateId = reference.stateId();
		operations[stateId] = (byte) operation.ordinal();
		firstParentStateIds[stateId] = firstParentStateId;
		secondParentStateIds[stateId] = secondParentStateId;
		operationRecipeIds[stateId] = operationRecipeId;
		payloadOwnerStateIds[stateId] = payloadOwnerStateId;
		dispositions[stateId] = (byte) FrontierStateDisposition.COMPOSABLE_PAYLOAD.ordinal();
		indexPayloadDerivation(stateId);
		return reference;
	}

	/**
	 * Appends a lineage-specific non-composable state without occupying the canonical slot for {@code key}.
	 *
	 * <p>
	 * This is used for typed local boundaries discovered while transforming a calibrated lineage. Keeping the declared
	 * key and parent provenance makes the degradation auditable, while deliberately omitting a payload prevents later
	 * operators from composing unsupported mass. Statistical exactness is independent of payload composability: an
	 * exact summary may describe an exact bound while this derived state remains
	 * {@link FrontierStateDisposition#BOUND_ONLY}.
	 */
	public EvidenceStateRef deriveSummary(
			FrontierStateKey key,
			EvidenceStateSummary summary,
			FrontierStateOperation operation,
			EvidenceStateRef firstParent,
			EvidenceStateRef secondParent,
			int operationRecipeId) {
		ensureOpen();
		Objects.requireNonNull(key, "key");
		Objects.requireNonNull(summary, "summary");
		Objects.requireNonNull(operation, "operation");
		int canonicalStateId = canonicalStateId(key);
		if (!canonicalUniverseSealed || canonicalStateId == 0) {
			throw new IllegalStateException("derived summary states require a predeclared canonical key");
		}
		if (operation != FrontierStateOperation.SUMMARY_ONLY
				&& operation != FrontierStateOperation.UNRESOLVED) {
			throw new IllegalArgumentException("derived summary operation must be non-replayable");
		}
		FrontierStateKey declaredKey = keys[canonicalStateId];
		validateProvenance(declaredKey, operation, firstParent, secondParent, operationRecipeId);
		int firstParentStateId = stateId(firstParent);
		int secondParentStateId = stateId(secondParent);
		FrontierStateDisposition disposition = FrontierStateDisposition.BOUND_ONLY;
		int derivedStateSlot = derivedStateSlot(declaredKey, declaredKey.frontier(), summary, operation, disposition,
				firstParentStateId, secondParentStateId, operationRecipeId, derivedStateSlots);
		int existingStateId = derivedStateSlots[derivedStateSlot];
		if (existingStateId != 0) {
			return references[existingStateId];
		}
		ensureDerivedStateCapacity(derivedStateCount + 1);
		derivedStateSlot = derivedStateSlot(declaredKey, declaredKey.frontier(), summary, operation, disposition,
				firstParentStateId, secondParentStateId, operationRecipeId, derivedStateSlots);

		int stateId = highWaterStateId + 1;
		ensureCapacity(stateId);
		long retainedBytes = summaryRetainedBytes(summary);
		reservePersistent(retainedBytes);
		EvidenceStateRef reference = materializeState(
				stateId,
				declaredKey,
				declaredKey.frontier(),
				summary,
				declaredKey.deterministicSeed());
		operations[stateId] = (byte) operation.ordinal();
		firstParentStateIds[stateId] = firstParentStateId;
		secondParentStateIds[stateId] = secondParentStateId;
		operationRecipeIds[stateId] = operationRecipeId;
		allocatedBytes += retainedBytes;
		updatePeak();
		highWaterStateId = stateId;
		derivedStateSlots[derivedStateSlot] = stateId;
		derivedStateCount++;
		return reference;
	}

	public FrontierPayloadStatus payloadStatus(EvidenceStateRef reference) {
		int stateId = validate(reference);
		return PAYLOAD_STATUSES[payloadStatuses[payloadStateId(stateId)]];
	}

	/**
	 * Returns the canonical continuation state for extensionally identical database-exact payloads.
	 *
	 * <p>
	 * Derivation states remain distinct for provenance and replay. A database-exact, calibration-free composable state
	 * may nevertheless use its collision-checked payload owner as a continuation identity: the complete canonical key
	 * and every payload byte are equal, so no supported suffix can distinguish the relation. Sampled, scaled,
	 * bound-only, opaque, and keyless states retain their lineage-specific identity.
	 */
	public EvidenceStateRef canonicalContinuationState(EvidenceStateRef reference) {
		int stateId = validate(reference);
		int ownerStateId = payloadStateId(stateId);
		if (reference.summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT
				|| dispositions[stateId] != (byte) FrontierStateDisposition.COMPOSABLE_PAYLOAD.ordinal()
				|| references[ownerStateId].summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT
				|| dispositions[ownerStateId] != (byte) FrontierStateDisposition.COMPOSABLE_PAYLOAD.ordinal()
				|| keys[stateId] == null
				|| !keys[stateId].equals(keys[ownerStateId])
				|| cumulativeWeightScales[stateId] != 1.0d
				|| nearestCalibration(stateId) != null) {
			return reference;
		}
		return references[ownerStateId];
	}

	public FrontierPayloadLease openPayload(EvidenceStateRef reference) {
		int stateId = validate(reference);
		int payloadStateId = payloadStateId(stateId);
		if (PAYLOAD_STATUSES[payloadStatuses[payloadStateId]] != FrontierPayloadStatus.RESIDENT) {
			throw new IllegalStateException("frontier payload is not resident");
		}
		if (payloadPinCounts[payloadStateId] == Integer.MAX_VALUE) {
			throw new IllegalStateException("frontier payload pin count exhausted");
		}
		if (openPayloadLeaseCount == Integer.MAX_VALUE) {
			throw new IllegalStateException("frontier payload lease count exhausted");
		}
		requireAvailableBytes(PAYLOAD_LEASE_BYTES, FrontierMemoryPurpose.PAYLOAD_LEASE);
		FrontierPayloadLease lease = new FrontierPayloadLease(
				this,
				reference,
				payloadStateId,
				payloadBlocks[payloadStateId],
				cumulativeWeightScales[stateId]);
		payloadPinCounts[payloadStateId]++;
		openPayloadLeaseCount++;
		temporaryReservedBytes += PAYLOAD_LEASE_BYTES;
		updatePeak();
		return lease;
	}

	public long evictPayload(EvidenceStateRef reference) {
		int stateId = validate(reference);
		if (keys[stateId] == null) {
			throw new IllegalStateException("only canonical payloads can be evicted");
		}
		if (payloadStatus(reference) != FrontierPayloadStatus.RESIDENT) {
			return 0L;
		}
		int payloadStateId = payloadStateId(stateId);
		if (payloadPinCounts[payloadStateId] != 0) {
			throw new IllegalStateException("pinned frontier payload cannot be evicted");
		}
		FrontierStateOperation operation = operation(reference);
		if (operation == FrontierStateOperation.SUMMARY_ONLY || operation == FrontierStateOperation.UNRESOLVED) {
			throw new IllegalStateException("frontier state does not have replayable provenance");
		}
		long released = payloadBytesByState[payloadStateId];
		removePayloadContentOwner(payloadStateId);
		payloadBlocks[payloadStateId] = null;
		payloadStatuses[payloadStateId] = (byte) FrontierPayloadStatus.EVICTED.ordinal();
		residentPayloadBytes -= released;
		return released;
	}

	public FrontierPayloadWriter newRematerializationWriter(
			EvidenceStateRef reference,
			int[] exactCountsByStratum,
			int[] residualCountsByStratum) {
		int stateId = validate(reference);
		int payloadStateId = payloadStateId(stateId);
		if (payloadStatus(reference) != FrontierPayloadStatus.EVICTED) {
			throw new IllegalStateException("frontier payload is not evicted");
		}
		if (sumCounts(exactCountsByStratum) != exactAtomCounts[payloadStateId]
				|| sumCounts(residualCountsByStratum) != residualParticleCounts[payloadStateId]) {
			throw new IllegalArgumentException("rematerialized payload counts do not match the immutable descriptor");
		}
		return new FrontierPayloadWriter(
				this,
				keys[payloadStateId],
				exactCountsByStratum,
				residualCountsByStratum,
				FrontierMemoryPurpose.REMATERIALIZATION);
	}

	public void restorePayload(EvidenceStateRef reference, FrontierPayloadWriter writer) {
		int stateId = validate(reference);
		int payloadStateId = payloadStateId(stateId);
		Objects.requireNonNull(writer, "writer");
		if (payloadStatus(reference) != FrontierPayloadStatus.EVICTED) {
			throw new IllegalStateException("frontier payload is not evicted");
		}
		if (writer.arena() != this || !keys[payloadStateId].equals(writer.key())) {
			throw new IllegalArgumentException("rematerialization writer belongs to another state");
		}
		try {
			FrontierPayloadBlock block = writer.finish();
			if (block.exactCount() != exactAtomCounts[payloadStateId]
					|| block.residualCount() != residualParticleCounts[payloadStateId]
					|| block.digestHigh() != payloadDigestHigh[payloadStateId]
					|| block.digestLow() != payloadDigestLow[payloadStateId]) {
				throw new IllegalStateException("rematerialized payload does not match its deterministic descriptor");
			}
			validatePayloadSummary(references[payloadStateId].summary(), block);
			int sharedPayloadOwnerStateId = payloadContentOwnerStateId(keys[payloadStateId], block);
			if (sharedPayloadOwnerStateId != 0 && sharedPayloadOwnerStateId != payloadStateId) {
				writer.close();
				redirectPayloadOwner(payloadStateId, sharedPayloadOwnerStateId);
				return;
			}
			long payloadBytes = block.retainedBytes;
			writer.transferToResident();
			payloadBlocks[payloadStateId] = block;
			payloadBytesByState[payloadStateId] = payloadBytes;
			payloadStatuses[payloadStateId] = (byte) FrontierPayloadStatus.RESIDENT.ordinal();
			indexPayloadContentOwner(payloadStateId);
		} catch (RuntimeException | Error failure) {
			writer.close();
			throw failure;
		}
	}

	public FrontierStateOperation operation(EvidenceStateRef reference) {
		return STATE_OPERATIONS[operations[validate(reference)]];
	}

	/** Returns how the state may participate in later Frontier transforms. */
	public FrontierStateDisposition disposition(EvidenceStateRef reference) {
		return STATE_DISPOSITIONS[dispositions[validate(reference)]];
	}

	/** Retains a typed, non-composable state across an operator whose tuple transform is not supported. */
	public EvidenceStateRef deriveOpaqueBoundary(EvidenceStateRef input, EvidenceStateSummary summary,
			int operationRecipeId) {
		return deriveBoundary(input, null, layout(input), summary, operationRecipeId,
				FrontierStateOperation.OPAQUE_BOUNDARY, FrontierStateDisposition.OPAQUE_BOUNDARY);
	}

	/** Retains both input lineages across a binary operator whose tuple transform is not supported. */
	public EvidenceStateRef deriveOpaqueBoundary(EvidenceStateRef firstInput, EvidenceStateRef secondInput,
			FrontierLayout outputLayout, EvidenceStateSummary summary, int operationRecipeId) {
		return deriveBoundary(firstInput, secondInput, outputLayout, summary, operationRecipeId,
				FrontierStateOperation.OPAQUE_BOUNDARY, FrontierStateDisposition.OPAQUE_BOUNDARY);
	}

	/** Retains conservative bounds and lineage through a non-composable unary transform. */
	public EvidenceStateRef deriveBoundBoundary(EvidenceStateRef input, FrontierLayout outputLayout,
			EvidenceStateSummary summary, int operationRecipeId) {
		return deriveBoundary(input, null, outputLayout, summary, operationRecipeId,
				FrontierStateOperation.BOUNDARY, FrontierStateDisposition.BOUND_ONLY);
	}

	/**
	 * Retains an input payload as tuple support for a bounded unary result without making the result composable.
	 *
	 * <p>
	 * The inherited tuples are only an upper-support relation: their weights are not asserted to describe the filtered
	 * result. Consumers may inspect tuple pairing and distinct-key support, but linear transforms must continue to
	 * reject this {@link FrontierStateDisposition#BOUND_ONLY} state.
	 * </p>
	 */
	public EvidenceStateRef deriveBoundSupport(EvidenceStateRef input, FrontierStateKey outputKey,
			EvidenceStateSummary summary, int operationRecipeId) {
		int inputStateId = validate(input);
		Objects.requireNonNull(outputKey, "outputKey");
		Objects.requireNonNull(summary, "summary");
		if (canonicalStateId(outputKey) == 0) {
			throw new IllegalArgumentException("bound support requires a declared canonical output key");
		}
		if (summary.guarantee().isComposablePointEstimate()) {
			throw new IllegalArgumentException("bound support requires a non-composable guarantee");
		}
		if (!layouts[inputStateId].equals(outputKey.frontier())) {
			throw new IllegalArgumentException("bound support must preserve the input Frontier layout");
		}
		int payloadOwnerStateId = payloadStateId(inputStateId);
		if (PAYLOAD_STATUSES[payloadStatuses[payloadOwnerStateId]] == FrontierPayloadStatus.NONE) {
			throw new IllegalArgumentException("bound support requires an input payload");
		}
		EvidenceStateRef support = deriveBoundary(input, null, outputKey.frontier(), summary, operationRecipeId,
				FrontierStateOperation.BOUNDARY, FrontierStateDisposition.BOUND_ONLY, outputKey);
		int supportStateId = support.stateId();
		payloadOwnerStateIds[supportStateId] = payloadOwnerStateId;
		cumulativeWeightScales[supportStateId] = cumulativeWeightScales[inputStateId];
		return support;
	}

	/** Retains conservative bounds and both lineages through a non-composable binary transform. */
	public EvidenceStateRef deriveBoundBoundary(EvidenceStateRef firstInput, EvidenceStateRef secondInput,
			FrontierLayout outputLayout, EvidenceStateSummary summary, int operationRecipeId) {
		return deriveBoundary(firstInput, secondInput, outputLayout, summary, operationRecipeId,
				FrontierStateOperation.BOUNDARY, FrontierStateDisposition.BOUND_ONLY);
	}

	private EvidenceStateRef deriveBoundary(EvidenceStateRef firstInput, EvidenceStateRef secondInput,
			FrontierLayout outputLayout, EvidenceStateSummary summary, int operationRecipeId,
			FrontierStateOperation operation, FrontierStateDisposition disposition) {
		int firstInputStateId = validate(firstInput);
		int secondInputStateId = secondInput == null ? 0 : validate(secondInput);
		Objects.requireNonNull(outputLayout, "outputLayout");
		boolean retainsCanonicalKey = operation == FrontierStateOperation.OPAQUE_BOUNDARY
				&& secondInputStateId == 0
				&& outputLayout.equals(layouts[firstInputStateId]);
		FrontierStateKey retainedKey = retainsCanonicalKey ? keys[firstInputStateId] : null;
		return deriveBoundary(firstInput, secondInput, outputLayout, summary, operationRecipeId, operation,
				disposition, retainedKey);
	}

	private EvidenceStateRef deriveBoundary(EvidenceStateRef firstInput, EvidenceStateRef secondInput,
			FrontierLayout outputLayout, EvidenceStateSummary summary, int operationRecipeId,
			FrontierStateOperation operation, FrontierStateDisposition disposition, FrontierStateKey retainedKey) {
		int firstInputStateId = validate(firstInput);
		int secondInputStateId = secondInput == null ? 0 : validate(secondInput);
		Objects.requireNonNull(outputLayout, "outputLayout");
		Objects.requireNonNull(summary, "summary");
		if (operationRecipeId < 0) {
			throw new IllegalArgumentException("operationRecipeId must be nonnegative");
		}
		int derivedStateSlot = derivedStateSlot(retainedKey, outputLayout, summary, operation, disposition,
				firstInputStateId, secondInputStateId, operationRecipeId, derivedStateSlots);
		int existingStateId = derivedStateSlots[derivedStateSlot];
		if (existingStateId != 0) {
			return references[existingStateId];
		}
		ensureDerivedStateCapacity(derivedStateCount + 1);
		derivedStateSlot = derivedStateSlot(retainedKey, outputLayout, summary, operation, disposition,
				firstInputStateId, secondInputStateId, operationRecipeId, derivedStateSlots);
		int stateId = highWaterStateId + 1;
		ensureCapacity(stateId);
		long retainedBytes = summaryRetainedBytes(summary);
		if (retainedKey == null) {
			retainedBytes = saturatedAdd(outputLayout.retainedBytes(), retainedBytes);
		}
		reservePersistent(retainedBytes);
		long seed = deterministicSeeds[firstInputStateId];
		if (secondInputStateId != 0) {
			seed ^= Long.rotateLeft(deterministicSeeds[secondInputStateId], 29);
		}
		EvidenceStateRef reference = materializeState(stateId, retainedKey, outputLayout, summary, seed);
		operations[stateId] = (byte) operation.ordinal();
		dispositions[stateId] = (byte) disposition.ordinal();
		firstParentStateIds[stateId] = firstInputStateId;
		secondParentStateIds[stateId] = secondInputStateId;
		operationRecipeIds[stateId] = operationRecipeId;
		allocatedBytes += retainedBytes;
		updatePeak();
		highWaterStateId = stateId;
		derivedStateSlots[derivedStateSlot] = stateId;
		derivedStateCount++;
		return reference;
	}

	/** Returns the number of database-exact atoms retained by this state's payload. */
	public int exactAtomCount(EvidenceStateRef reference) {
		return exactAtomCounts[payloadStateId(validate(reference))];
	}

	/** Returns the number of sampled particles retained by this state's payload. */
	public int residualParticleCount(EvidenceStateRef reference) {
		return residualParticleCounts[payloadStateId(validate(reference))];
	}

	public int parentCount(EvidenceStateRef reference) {
		int stateId = validate(reference);
		int count = firstParentStateIds[stateId] == 0 ? 0 : 1;
		return secondParentStateIds[stateId] == 0 ? count : count + 1;
	}

	public EvidenceStateRef parent(EvidenceStateRef reference, int index) {
		int stateId = validate(reference);
		int parentCount = parentCount(reference);
		if (index < 0 || index >= parentCount) {
			throw new IndexOutOfBoundsException("parent " + index);
		}
		int parentStateId = index == 0 ? firstParentStateIds[stateId] : secondParentStateIds[stateId];
		return references[parentStateId];
	}

	public int operationRecipeId(EvidenceStateRef reference) {
		return operationRecipeIds[validate(reference)];
	}

	/**
	 * Detaches the requested states and their complete transitive lineage from this query-local arena.
	 *
	 * <p>
	 * The returned bundle owns every primitive payload array it exposes. Its state ordinals are bundle-local and
	 * topological; ordinal zero remains reserved for “no state”. Resident payload leases are held only while their
	 * arrays are copied. Evicted database-exact payloads retain a replay descriptor and their immutable content digest.
	 */
	public FrontierEvidenceBundle exportEvidence(int[] requestedStateIds) {
		ensureOpen();
		Objects.requireNonNull(requestedStateIds, "requestedStateIds");
		int[] requested = requestedStateIds.clone();
		for (int stateId : requested) {
			validateExportStateId(stateId);
		}

		byte[] visit = new byte[highWaterStateId + 1];
		int[] topologicalStateIds = new int[Math.max(1, materializedCount)];
		int topologicalCount = 0;
		int[] stackStateIds = new int[Math.max(1, Math.min(highWaterStateId, 16))];
		byte[] stackEdges = new byte[stackStateIds.length];
		for (int requestedStateId : requested) {
			if (requestedStateId == 0 || visit[requestedStateId] == 2) {
				continue;
			}
			int depth = 0;
			stackStateIds[0] = requestedStateId;
			stackEdges[0] = 0;
			while (depth >= 0) {
				int stateId = stackStateIds[depth];
				if (visit[stateId] == 0) {
					visit[stateId] = 1;
				}
				int parentStateId = switch (stackEdges[depth]++) {
				case 0 -> firstParentStateIds[stateId];
				case 1 -> secondParentStateIds[stateId];
				default -> -1;
				};
				if (parentStateId >= 0) {
					if (parentStateId == 0 || visit[parentStateId] == 2) {
						continue;
					}
					validateExportStateId(parentStateId);
					if (visit[parentStateId] == 1) {
						throw new IllegalStateException("cyclic Frontier state lineage");
					}
					depth++;
					if (depth == stackStateIds.length) {
						int replacement = Math.min(highWaterStateId, Math.multiplyExact(stackStateIds.length, 2));
						stackStateIds = Arrays.copyOf(stackStateIds, replacement);
						stackEdges = Arrays.copyOf(stackEdges, replacement);
					}
					stackStateIds[depth] = parentStateId;
					stackEdges[depth] = 0;
					continue;
				}
				visit[stateId] = 2;
				if (topologicalCount == topologicalStateIds.length) {
					topologicalStateIds = Arrays.copyOf(topologicalStateIds,
							Math.multiplyExact(topologicalStateIds.length, 2));
				}
				topologicalStateIds[topologicalCount++] = stateId;
				depth--;
			}
		}

		int stateArrayLength = topologicalCount + 1;
		int[] stateOrdinals = new int[highWaterStateId + 1];
		for (int index = 0; index < topologicalCount; index++) {
			stateOrdinals[topologicalStateIds[index]] = index + 1;
		}
		int[] requestedOrdinals = new int[requested.length];
		for (int index = 0; index < requested.length; index++) {
			requestedOrdinals[index] = requested[index] == 0 ? 0 : stateOrdinals[requested[index]];
		}

		FrontierStateKey[] detachedKeys = new FrontierStateKey[stateArrayLength];
		FrontierLayout[] detachedLayouts = new FrontierLayout[stateArrayLength];
		EvidenceStateSummary[] detachedSummaries = new EvidenceStateSummary[stateArrayLength];
		FrontierStateOperation[] detachedOperations = new FrontierStateOperation[stateArrayLength];
		FrontierStateDisposition[] detachedDispositions = new FrontierStateDisposition[stateArrayLength];
		int[] detachedFirstParents = new int[stateArrayLength];
		int[] detachedSecondParents = new int[stateArrayLength];
		int[] detachedRecipeIds = new int[stateArrayLength];
		EvidenceCalibrationSummary[] detachedCalibrations = new EvidenceCalibrationSummary[stateArrayLength];
		FrontierEvidenceBundle.Payload[] detachedPayloads = new FrontierEvidenceBundle.Payload[stateArrayLength];
		boolean[] detachedSharesFirstParentPayload = new boolean[stateArrayLength];
		long[] detachedDigestHigh = new long[stateArrayLength];
		long[] detachedDigestLow = new long[stateArrayLength];
		detachedPayloads[0] = FrontierEvidenceBundle.Payload.none();
		long retainedBytes = detachedBundleMetadataBytes(requested.length, stateArrayLength);
		for (int index = 0; index < topologicalCount; index++) {
			int stateId = topologicalStateIds[index];
			int ordinal = index + 1;
			detachedKeys[ordinal] = keys[stateId];
			detachedLayouts[ordinal] = layouts[stateId];
			detachedSummaries[ordinal] = references[stateId].summary();
			detachedOperations[ordinal] = STATE_OPERATIONS[operations[stateId]];
			detachedDispositions[ordinal] = STATE_DISPOSITIONS[dispositions[stateId]];
			detachedFirstParents[ordinal] = stateOrdinals[firstParentStateIds[stateId]];
			detachedSecondParents[ordinal] = stateOrdinals[secondParentStateIds[stateId]];
			detachedRecipeIds[ordinal] = operationRecipeIds[stateId];
			detachedCalibrations[ordinal] = calibrations[stateId];
			detachedSharesFirstParentPayload[ordinal] = inheritsFirstParentPayload(stateId);
			FrontierEvidenceBundle.Payload payload = detachPayload(stateId);
			detachedPayloads[ordinal] = payload;
			retainedBytes = saturatedAdd(retainedBytes, payload.retainedBytes());
			long firstDigestHigh = detachedDigestHigh[detachedFirstParents[ordinal]];
			long firstDigestLow = detachedDigestLow[detachedFirstParents[ordinal]];
			long secondDigestHigh = detachedDigestHigh[detachedSecondParents[ordinal]];
			long secondDigestLow = detachedDigestLow[detachedSecondParents[ordinal]];
			detachedDigestHigh[ordinal] = detachedStateDigest(
					0x243f6a8885a308d3L,
					stateId,
					payload.digestHigh(),
					detachedSharesFirstParentPayload[ordinal],
					firstDigestHigh,
					secondDigestHigh);
			detachedDigestLow[ordinal] = detachedStateDigest(
					0x13198a2e03707344L,
					stateId,
					payload.digestLow(),
					detachedSharesFirstParentPayload[ordinal],
					firstDigestLow,
					secondDigestLow);
		}
		return new FrontierEvidenceBundle(
				requestedOrdinals,
				detachedKeys,
				detachedLayouts,
				detachedSummaries,
				detachedOperations,
				detachedDispositions,
				detachedFirstParents,
				detachedSecondParents,
				detachedRecipeIds,
				detachedCalibrations,
				detachedPayloads,
				detachedSharesFirstParentPayload,
				detachedDigestHigh,
				detachedDigestLow,
				retainedBytes);
	}

	/**
	 * Imports one detached evidence graph into an empty query-local arena.
	 *
	 * <p>
	 * The returned references align with the bundle's requested-state positions. Inline payloads are copied into this
	 * arena, replayable exact descriptors remain evicted until their store-specific recipe is replayed, and ordinal
	 * zero remains {@code null}. No resource owned by the source arena is retained.
	 */
	public EvidenceStateRef[] importEvidence(FrontierEvidenceBundle bundle) {
		ensureOpen();
		Objects.requireNonNull(bundle, "bundle");
		if (highWaterStateId != 0 || canonicalCount != 0 || canonicalUniverseSealed) {
			throw new IllegalStateException("detached Frontier evidence requires an empty target arena");
		}

		HashMap<FrontierStateKey, Integer> firstOrdinalByKey = new HashMap<>();
		FrontierStateKey[] declaredKeys = new FrontierStateKey[bundle.stateCount()];
		int declaredCount = 0;
		for (int ordinal = 1; ordinal <= bundle.stateCount(); ordinal++) {
			FrontierStateKey key = bundle.key(ordinal);
			if (key != null && firstOrdinalByKey.putIfAbsent(key, ordinal) == null) {
				declaredKeys[declaredCount++] = key;
			}
		}
		declareCanonicalStates(Arrays.copyOf(declaredKeys, declaredCount));

		EvidenceStateRef[] importedByOrdinal = new EvidenceStateRef[bundle.stateCount() + 1];
		for (int ordinal = 1; ordinal <= bundle.stateCount(); ordinal++) {
			FrontierStateKey key = bundle.key(ordinal);
			EvidenceStateRef firstParent = importedByOrdinal[bundle.firstParentOrdinal(ordinal)];
			EvidenceStateRef secondParent = importedByOrdinal[bundle.secondParentOrdinal(ordinal)];
			FrontierStateOperation operation = bundle.operation(ordinal);
			EvidenceStateSummary summary = bundle.summary(ordinal);
			int recipeId = bundle.operationRecipeId(ordinal);
			boolean canonicalPayload = key != null && firstOrdinalByKey.get(key) == ordinal;
			EvidenceStateRef imported;
			if (operation == FrontierStateOperation.CALIBRATE) {
				if (firstParent == null || bundle.calibration(ordinal) == null) {
					throw new IllegalArgumentException("detached calibration is missing its raw parent or overlay");
				}
				imported = calibrate(firstParent, bundle.calibration(ordinal), recipeId);
			} else if (operation == FrontierStateOperation.OPAQUE_BOUNDARY) {
				if (firstParent == null) {
					throw new IllegalArgumentException("detached opaque boundary is missing its parent");
				}
				imported = deriveOpaqueBoundary(firstParent, secondParent, bundle.layout(ordinal), summary, recipeId);
			} else if (operation == FrontierStateOperation.BOUNDARY) {
				if (firstParent == null) {
					throw new IllegalArgumentException("detached bound boundary is missing its parent");
				}
				if (bundle.sharesFirstParentPayload(ordinal)) {
					if (secondParent != null || key == null) {
						throw new IllegalArgumentException(
								"detached bound support requires one parent and a canonical key");
					}
					imported = deriveBoundSupport(firstParent, key, summary, recipeId);
				} else {
					imported = deriveBoundBoundary(firstParent, secondParent, bundle.layout(ordinal), summary,
							recipeId);
				}
			} else {
				imported = switch (bundle.payloadKind(ordinal)) {
				case INLINE -> importInlinePayload(bundle, ordinal, key, summary, operation, firstParent,
						secondParent, recipeId, canonicalPayload);
				case REPLAYABLE_EXACT -> importReplayableExact(bundle, ordinal, key, summary, operation,
						firstParent, secondParent, recipeId, canonicalPayload);
				case NONE -> importSummaryOnly(key, bundle.layout(ordinal), summary, operation, firstParent,
						secondParent, recipeId);
				};
			}
			if (disposition(imported) != bundle.disposition(ordinal)) {
				throw new IllegalStateException("detached Frontier disposition changed during import");
			}
			if (bundle.sharesFirstParentPayload(ordinal) && !sharesFirstParentPayload(imported.stateId())) {
				throw new IllegalStateException("detached Frontier payload ownership changed during import");
			}
			importedByOrdinal[ordinal] = imported;
		}

		EvidenceStateRef[] requested = new EvidenceStateRef[bundle.requestedStateCount()];
		for (int index = 0; index < requested.length; index++) {
			requested[index] = importedByOrdinal[bundle.requestedStateOrdinal(index)];
		}
		return requested;
	}

	private EvidenceStateRef importInlinePayload(FrontierEvidenceBundle bundle, int ordinal, FrontierStateKey key,
			EvidenceStateSummary summary, FrontierStateOperation operation, EvidenceStateRef firstParent,
			EvidenceStateRef secondParent, int recipeId, boolean canonicalPayload) {
		if (key == null) {
			throw new IllegalArgumentException("detached inline payload is missing its canonical key");
		}
		FrontierMaskStrata masks = bundle.masks(ordinal);
		int strata = masks.stratumCount();
		int width = masks.layout().size();
		int[] exactCounts = new int[strata];
		int[] residualCounts = new int[strata];
		for (int stratum = 0; stratum < strata; stratum++) {
			exactCounts[stratum] = bundle.exactCount(ordinal, stratum);
			residualCounts[stratum] = bundle.residualCount(ordinal, stratum);
		}
		try (FrontierPayloadWriter writer = newPayloadWriter(key, exactCounts, residualCounts)) {
			long[] tuple = new long[width];
			for (int stratum = 0; stratum < strata; stratum++) {
				for (int index = 0; index < exactCounts[stratum]; index++) {
					for (int slot = 0; slot < width; slot++) {
						tuple[slot] = bundle.exactTermId(ordinal, stratum, index, slot);
					}
					writer.putExact(stratum, index, bundle.exactWeight(ordinal, stratum, index), tuple, 0);
				}
				for (int index = 0; index < residualCounts[stratum]; index++) {
					for (int slot = 0; slot < width; slot++) {
						tuple[slot] = bundle.residualTermId(ordinal, stratum, index, slot);
					}
					writer.putResidual(stratum, index, bundle.residualWeight(ordinal, stratum, index), tuple, 0);
				}
			}
			return canonicalPayload
					? internPayload(key, summary, operation, firstParent, secondParent, recipeId, writer)
					: derivePayload(key, summary, operation, firstParent, secondParent, recipeId, writer);
		}
	}

	private EvidenceStateRef importSummaryOnly(FrontierStateKey key, FrontierLayout layout,
			EvidenceStateSummary summary, FrontierStateOperation operation, EvidenceStateRef firstParent,
			EvidenceStateRef secondParent, int recipeId) {
		if (key == null) {
			if (firstParent != null || secondParent != null) {
				throw new IllegalArgumentException("unkeyed detached summaries cannot retain lineage");
			}
			return append(layout, summary);
		}
		if (operation != FrontierStateOperation.SUMMARY_ONLY
				&& operation != FrontierStateOperation.UNRESOLVED) {
			throw new IllegalArgumentException("detached state lost a required payload");
		}
		return deriveSummary(key, summary, operation, firstParent, secondParent, recipeId);
	}

	private EvidenceStateRef importReplayableExact(FrontierEvidenceBundle bundle, int ordinal,
			FrontierStateKey key, EvidenceStateSummary summary, FrontierStateOperation operation,
			EvidenceStateRef firstParent, EvidenceStateRef secondParent, int recipeId, boolean canonicalPayload) {
		if (key == null || summary.guarantee() != EvidenceGuarantee.DATABASE_EXACT) {
			throw new IllegalArgumentException("replayable detached evidence must be database-exact and keyed");
		}
		validateProvenance(key, operation, firstParent, secondParent, recipeId);
		int existingStateId = payloadDerivationStateId(
				key, operation, stateId(firstParent), stateId(secondParent), recipeId);
		if (existingStateId != 0) {
			if (!references[existingStateId].summary().equals(summary)
					|| payloadStatuses[existingStateId] != (byte) FrontierPayloadStatus.EVICTED.ordinal()
					|| payloadDigestHigh[existingStateId] != bundle.payloadDigestHigh(ordinal)
					|| payloadDigestLow[existingStateId] != bundle.payloadDigestLow(ordinal)) {
				throw new IllegalStateException("replayable derivation rematerialized with different evidence");
			}
			return references[existingStateId];
		}
		ensurePayloadDerivationCapacity(payloadDerivationCount + 1);
		EvidenceStateRef reference;
		if (canonicalPayload) {
			reference = intern(key, summary);
		} else {
			int stateId = highWaterStateId + 1;
			ensureCapacity(stateId);
			long retainedBytes = summaryRetainedBytes(summary);
			reservePersistent(retainedBytes);
			reference = materializeState(stateId, key, key.frontier(), summary, key.deterministicSeed());
			allocatedBytes += retainedBytes;
			updatePeak();
			highWaterStateId = stateId;
		}
		int stateId = reference.stateId();
		operations[stateId] = (byte) operation.ordinal();
		firstParentStateIds[stateId] = stateId(firstParent);
		secondParentStateIds[stateId] = stateId(secondParent);
		operationRecipeIds[stateId] = recipeId;
		payloadOwnerStateIds[stateId] = stateId;
		payloadDigestHigh[stateId] = bundle.payloadDigestHigh(ordinal);
		payloadDigestLow[stateId] = bundle.payloadDigestLow(ordinal);
		payloadStatuses[stateId] = (byte) FrontierPayloadStatus.EVICTED.ordinal();
		dispositions[stateId] = (byte) FrontierStateDisposition.COMPOSABLE_PAYLOAD.ordinal();
		indexPayloadDerivation(stateId);
		return reference;
	}

	public long persistentMetadataBytes() {
		ensureOpen();
		return allocatedBytes;
	}

	public long residentPayloadBytes() {
		ensureOpen();
		return residentPayloadBytes;
	}

	public long temporaryReservedBytes() {
		ensureOpen();
		return temporaryReservedBytes;
	}

	public long remainingBytes() {
		ensureOpen();
		return memoryBudgetBytes - totalReservedBytes();
	}

	public long peakReservedBytes() {
		ensureOpen();
		return peakReservedBytes;
	}

	public FrontierMemoryReservation reserveTemporary(long bytes, FrontierMemoryPurpose purpose) {
		ensureOpen();
		Objects.requireNonNull(purpose, "purpose");
		if (bytes < 0L || openReservationCount == Integer.MAX_VALUE) {
			throw new FrontierMemoryLimitException(
					bytes < 0L ? Long.MAX_VALUE : bytes, totalReservedBytes(), memoryBudgetBytes, purpose);
		}
		long chargedBytes = saturatedAdd(bytes, MEMORY_RESERVATION_BYTES);
		requireAvailableBytes(chargedBytes, purpose);
		FrontierMemoryReservation reservation = new FrontierMemoryReservation(this, bytes, chargedBytes, purpose);
		temporaryReservedBytes += chargedBytes;
		openReservationCount++;
		updatePeak();
		return reservation;
	}

	private EvidenceStateRef materializeState(int stateId, FrontierStateKey key, FrontierLayout layout,
			EvidenceStateSummary summary, long deterministicSeed) {
		EvidenceStateRef reference = new EvidenceStateRef(token, stateId, summary);
		pointRows[stateId] = summary.pointRows();
		lowerRows[stateId] = summary.lowerRows();
		upperRows[stateId] = summary.upperRows();
		confidence[stateId] = summary.confidence();
		inheritedVariance[stateId] = summary.inheritedVariance();
		mutationVariance[stateId] = summary.mutationVariance();
		resamplingVariance[stateId] = summary.resamplingVariance();
		effectiveSampleSize[stateId] = summary.effectiveSampleSize();
		maximumWeightFraction[stateId] = summary.maximumWeightFraction();
		certifiedUpperBound[stateId] = summary.certifiedUpperBound();
		cumulativeWeightScales[stateId] = 1.0d;
		intervalKinds[stateId] = summary.intervalKind().ordinal();
		guarantees[stateId] = summary.guarantee().ordinal();
		zeroStatuses[stateId] = summary.zeroStatus().ordinal();
		layouts[stateId] = layout;
		degradationReasons[stateId] = summary.degradationReason();
		keys[stateId] = key;
		deterministicSeeds[stateId] = deterministicSeed;
		operations[stateId] = (byte) FrontierStateOperation.SUMMARY_ONLY.ordinal();
		dispositions[stateId] = (byte) FrontierStateDisposition.BOUND_ONLY.ordinal();
		payloadStatuses[stateId] = (byte) FrontierPayloadStatus.NONE.ordinal();
		references[stateId] = reference;
		materialized[stateId] = true;
		materializedCount++;
		return reference;
	}

	public EvidenceStateSummary summary(EvidenceStateRef reference) {
		return references[validate(reference)].summary();
	}

	public FrontierLayout layout(EvidenceStateRef reference) {
		return layouts[validate(reference)];
	}

	public boolean owns(EvidenceStateRef reference) {
		return !closed
				&& reference != null
				&& reference.arenaToken() == token
				&& reference.stateId() > 0
				&& reference.stateId() <= highWaterStateId
				&& materialized[reference.stateId()]
				&& references[reference.stateId()] == reference;
	}

	public int size() {
		ensureOpen();
		return materializedCount;
	}

	public long memoryBudgetBytes() {
		return memoryBudgetBytes;
	}

	public long allocatedBytes() {
		return pointRows == null ? 0L : totalReservedBytes();
	}

	@Override
	public void close() {
		if (closed) {
			return;
		}
		if (openPayloadLeaseCount != 0 || openReservationCount != 0) {
			throw new IllegalStateException("frontier state arena has outstanding leases or memory reservations");
		}
		closed = true;
		pointRows = null;
		lowerRows = null;
		upperRows = null;
		confidence = null;
		inheritedVariance = null;
		mutationVariance = null;
		resamplingVariance = null;
		effectiveSampleSize = null;
		maximumWeightFraction = null;
		certifiedUpperBound = null;
		cumulativeWeightScales = null;
		intervalKinds = null;
		guarantees = null;
		zeroStatuses = null;
		layouts = null;
		degradationReasons = null;
		keys = null;
		deterministicSeeds = null;
		references = null;
		materialized = null;
		operations = null;
		dispositions = null;
		firstParentStateIds = null;
		secondParentStateIds = null;
		operationRecipeIds = null;
		payloadOwnerStateIds = null;
		payloadBlocks = null;
		calibrations = null;
		payloadStatuses = null;
		payloadPinCounts = null;
		exactAtomCounts = null;
		residualParticleCounts = null;
		payloadBytesByState = null;
		payloadDigestHigh = null;
		payloadDigestLow = null;
		canonicalSlots = null;
		calibrationSlots = null;
		derivedStateSlots = null;
		payloadDerivationSlots = null;
		payloadContentSlots = null;
		canonicalCount = 0;
		calibrationCount = 0;
		derivedStateCount = 0;
		payloadDerivationCount = 0;
		payloadContentCount = 0;
		highWaterStateId = 0;
		materializedCount = 0;
		allocatedBytes = 0L;
		residentPayloadBytes = 0L;
		temporaryReservedBytes = 0L;
		peakReservedBytes = 0L;
		openPayloadLeaseCount = 0;
		openReservationCount = 0;
		canonicalUniverseSealed = false;
	}

	private int validate(EvidenceStateRef reference) {
		ensureOpen();
		if (!owns(reference)) {
			throw new IllegalArgumentException("evidence state does not belong to this arena");
		}
		return reference.stateId();
	}

	private void validateExportStateId(int stateId) {
		if (stateId < 0 || stateId > highWaterStateId || (stateId != 0 && !materialized[stateId])) {
			throw new IllegalArgumentException("unknown Frontier state ID " + stateId);
		}
	}

	private FrontierEvidenceBundle.Payload detachPayload(int stateId) {
		if (inheritsFirstParentPayload(stateId)) {
			return FrontierEvidenceBundle.Payload.none();
		}
		int ownerStateId = payloadStateId(stateId);
		FrontierPayloadStatus status = PAYLOAD_STATUSES[payloadStatuses[ownerStateId]];
		if (status == FrontierPayloadStatus.NONE) {
			return FrontierEvidenceBundle.Payload.none();
		}
		if (status == FrontierPayloadStatus.EVICTED) {
			if (references[stateId].summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT) {
				return FrontierEvidenceBundle.Payload.none();
			}
			return FrontierEvidenceBundle.Payload.replayableExact(
					keys[ownerStateId].maskStrata(),
					payloadDigestHigh[ownerStateId],
					payloadDigestLow[ownerStateId]);
		}
		FrontierPayloadBlock block = payloadBlocks[ownerStateId];
		if (block == null) {
			throw new IllegalStateException("resident Frontier payload is unavailable for detachment");
		}
		return FrontierEvidenceBundle.Payload.inlineShared(
				block, payloadDigestHigh[ownerStateId], payloadDigestLow[ownerStateId]);
	}

	private long detachedStateDigest(long seed, int stateId, long payloadDigest, boolean sharesFirstParentPayload,
			long firstParentDigest,
			long secondParentDigest) {
		long hash = mixDetachedDigest(seed, keys[stateId] == null ? 0L : keys[stateId].stableHash());
		hash = mixDetachedDigest(hash, layouts[stateId].hashCode());
		hash = mixDetachedDigest(hash, references[stateId].summary().hashCode());
		hash = mixDetachedDigest(hash, operations[stateId]);
		hash = mixDetachedDigest(hash, operationRecipeIds[stateId]);
		hash = mixDetachedDigest(hash, calibrations[stateId] == null ? 0L : calibrations[stateId].hashCode());
		hash = mixDetachedDigest(hash, payloadDigest);
		hash = mixDetachedDigest(hash, sharesFirstParentPayload ? 1L : 0L);
		hash = mixDetachedDigest(hash, firstParentDigest);
		hash = mixDetachedDigest(hash, secondParentDigest);
		return avalancheDetachedDigest(hash);
	}

	private static long detachedBundleMetadataBytes(int requestedCount, int stateArrayLength) {
		long bytes = arrayBytes(requestedCount, Integer.BYTES);
		bytes = saturatedAdd(bytes, 12L * arrayBytes(stateArrayLength, Long.BYTES));
		bytes = saturatedAdd(bytes, arrayBytes(stateArrayLength, Byte.BYTES));
		return bytes;
	}

	private boolean sharesFirstParentPayload(int stateId) {
		int firstParentStateId = firstParentStateIds[stateId];
		return firstParentStateId != 0
				&& payloadOwnerStateIds[stateId] != 0
				&& payloadStateId(stateId) == payloadStateId(firstParentStateId);
	}

	private boolean inheritsFirstParentPayload(int stateId) {
		FrontierStateOperation operation = STATE_OPERATIONS[operations[stateId]];
		return (operation == FrontierStateOperation.CALIBRATE || operation == FrontierStateOperation.BOUNDARY)
				&& sharesFirstParentPayload(stateId);
	}

	private static long mixDetachedDigest(long hash, long value) {
		long mixed = value + 0x9e3779b97f4a7c15L + (hash << 6) + (hash >>> 2);
		return hash ^ mixed;
	}

	private static long avalancheDetachedDigest(long value) {
		long mixed = value;
		mixed ^= mixed >>> 33;
		mixed *= 0xff51afd7ed558ccdL;
		mixed ^= mixed >>> 33;
		mixed *= 0xc4ceb9fe1a85ec53L;
		return mixed ^ mixed >>> 33;
	}

	void releasePayload(EvidenceStateRef reference, int payloadOwnerStateId) {
		int stateId = validate(reference);
		if (payloadStateId(stateId) != payloadOwnerStateId) {
			throw new IllegalStateException("frontier payload owner changed while leased");
		}
		if (payloadPinCounts[payloadOwnerStateId] <= 0) {
			throw new IllegalStateException("frontier payload is not pinned");
		}
		if (openPayloadLeaseCount <= 0 || temporaryReservedBytes < PAYLOAD_LEASE_BYTES) {
			throw new IllegalStateException("invalid Frontier payload-lease release");
		}
		payloadPinCounts[payloadOwnerStateId]--;
		openPayloadLeaseCount--;
		temporaryReservedBytes -= PAYLOAD_LEASE_BYTES;
	}

	void releaseTemporary(long bytes) {
		ensureOpen();
		if (bytes < 0L || openReservationCount <= 0 || temporaryReservedBytes < bytes) {
			throw new IllegalStateException("invalid Frontier temporary-memory release");
		}
		temporaryReservedBytes -= bytes;
		openReservationCount--;
	}

	void transferTemporaryToResident(long reservedBytes, long payloadBytes) {
		ensureOpen();
		if (reservedBytes < 0L
				|| payloadBytes < 0L
				|| payloadBytes > reservedBytes
				|| openReservationCount <= 0
				|| temporaryReservedBytes < reservedBytes) {
			throw new IllegalStateException("invalid Frontier payload-memory transfer");
		}
		temporaryReservedBytes -= reservedBytes;
		residentPayloadBytes += payloadBytes;
		openReservationCount--;
	}

	void transferTemporaryToMetadata(long reservedBytes, long metadataBytes) {
		ensureOpen();
		if (reservedBytes < 0L
				|| metadataBytes < 0L
				|| metadataBytes > reservedBytes
				|| openReservationCount <= 0
				|| temporaryReservedBytes < reservedBytes) {
			throw new IllegalStateException("invalid Frontier metadata-memory transfer");
		}
		temporaryReservedBytes -= reservedBytes;
		allocatedBytes += metadataBytes;
		openReservationCount--;
	}

	private int canonicalStateId(FrontierStateKey key) {
		int slot = canonicalSlot(key, canonicalSlots);
		return canonicalSlots[slot];
	}

	private void validateExistingPayload(
			int stateId,
			EvidenceStateSummary summary,
			FrontierStateOperation operation,
			EvidenceStateRef firstParent,
			EvidenceStateRef secondParent,
			int operationRecipeId,
			FrontierPayloadBlock block) {
		int payloadOwnerStateId = payloadStateId(stateId);
		if (!references[stateId].summary().equals(summary)
				|| operations[stateId] != (byte) operation.ordinal()
				|| firstParentStateIds[stateId] != stateId(firstParent)
				|| secondParentStateIds[stateId] != stateId(secondParent)
				|| operationRecipeIds[stateId] != operationRecipeId
				|| payloadStatuses[payloadOwnerStateId] != (byte) FrontierPayloadStatus.RESIDENT.ordinal()
				|| payloadBlocks[payloadOwnerStateId] == null
				|| !payloadBlocks[payloadOwnerStateId].sameContent(block)) {
			throw new IllegalStateException("canonical state rematerialized with different payload or provenance");
		}
	}

	private void validatePayloadSummary(EvidenceStateSummary summary, FrontierPayloadBlock block) {
		if (Double.doubleToLongBits(block.pointRows()) != Double.doubleToLongBits(summary.pointRows())) {
			throw new IllegalArgumentException("frontier payload mass must equal the state point estimate");
		}
		if (summary.guarantee() == EvidenceGuarantee.DATABASE_EXACT && block.residualCount() != 0) {
			throw new IllegalArgumentException("database-exact evidence cannot contain residual particles");
		}
		if (summary.zeroStatus() == EvidenceZeroStatus.EXACT_ZERO
				&& (block.exactCount() != 0 || block.residualCount() != 0)) {
			throw new IllegalArgumentException("EXACT_ZERO requires an empty frontier payload");
		}
		if (summary.pointRows() > 0.0d && block.exactCount() == 0 && block.residualCount() == 0) {
			throw new IllegalArgumentException("positive composable evidence requires a payload");
		}
		if (!sameDiagnostic(summary.effectiveSampleSize(), block.effectiveSampleSize())
				|| !sameDiagnostic(summary.maximumWeightFraction(), block.maximumWeightFraction())) {
			throw new IllegalArgumentException("particle diagnostics must be derived from residual weights");
		}
	}

	private void validateProvenance(
			FrontierStateKey childKey,
			FrontierStateOperation operation,
			EvidenceStateRef firstParent,
			EvidenceStateRef secondParent,
			int operationRecipeId) {
		if (operationRecipeId < 0) {
			throw new IllegalArgumentException("operationRecipeId must be nonnegative");
		}
		if (secondParent != null && firstParent == null) {
			throw new IllegalArgumentException("second parent requires a first parent");
		}
		int parentCount = firstParent == null ? 0 : secondParent == null ? 1 : 2;
		boolean valid = switch (operation) {
		case EXACT_LEAF, COORDINATED_STAR, SUMMARY_ONLY -> parentCount == 0;
		case BRIDGE_TRANSFER, BRIDGE_MUTATION, PROBE_FACTOR, RESOLVE_OUTER_KERNEL, RESOLVE_OUTER_EXPANSION, PROJECT, ALIGN, RESTRICT, DISTINCT, GROUP, CALIBRATE, OPAQUE_BOUNDARY, EXACT_REMEASURE -> parentCount == 1;
		case BOUNDARY -> parentCount >= 1;
		case JOIN, CARTESIAN, AVERAGE_DESIGN_LANES, UNION, INTERSECTION -> parentCount == 2;
		case UNRESOLVED -> true;
		};
		if (!valid) {
			throw new IllegalArgumentException("invalid parent arity for " + operation);
		}
		validateParentCompatibility(childKey, firstParent, false);
		validateParentCompatibility(childKey, secondParent,
				operation == FrontierStateOperation.CARTESIAN
						|| operation == FrontierStateOperation.AVERAGE_DESIGN_LANES);
	}

	private void validateParentCompatibility(FrontierStateKey childKey, EvidenceStateRef parent,
			boolean requireIndependentLane) {
		if (parent == null) {
			return;
		}
		int parentStateId = validate(parent);
		FrontierStateKey parentKey = keys[parentStateId];
		FrontierPayloadStatus parentStatus = payloadStatus(parent);
		if (parentKey == null
				|| dispositions[parentStateId] != (byte) FrontierStateDisposition.COMPOSABLE_PAYLOAD.ordinal()
				|| !parent.summary().guarantee().isComposablePointEstimate()
				|| (parentStatus != FrontierPayloadStatus.RESIDENT && parentStatus != FrontierPayloadStatus.EVICTED)) {
			throw new IllegalArgumentException("frontier transforms require canonical composable payload parents");
		}
		boolean sameSnapshot = parentKey.snapshotStoreIdHigh() == childKey.snapshotStoreIdHigh()
				&& parentKey.snapshotStoreIdLow() == childKey.snapshotStoreIdLow()
				&& parentKey.snapshotEpoch() == childKey.snapshotEpoch()
				&& parentKey.seedVersion() == childKey.seedVersion();
		boolean compatibleLane = requireIndependentLane
				? parentKey.laneFamily() == childKey.laneFamily()
						&& parentKey.laneIndex() != childKey.laneIndex()
				: parentKey.laneFamily() == childKey.laneFamily()
						&& parentKey.laneIndex() == childKey.laneIndex();
		if (!sameSnapshot || !compatibleLane) {
			throw new IllegalArgumentException("frontier parent and child sampling identities differ");
		}
	}

	private static void validateExactPayloadOperation(
			FrontierStateOperation operation,
			EvidenceStateSummary summary) {
		if ((operation == FrontierStateOperation.EXACT_LEAF
				|| operation == FrontierStateOperation.EXACT_REMEASURE)
				&& summary.guarantee() != EvidenceGuarantee.DATABASE_EXACT) {
			throw new IllegalArgumentException(operation + " requires database-exact evidence");
		}
	}

	private void validateInheritedRandomMass(
			FrontierStateOperation operation,
			EvidenceStateRef firstParent,
			EvidenceStateRef secondParent,
			FrontierPayloadBlock child) {
		if (operation == FrontierStateOperation.EXACT_REMEASURE || child.exactCount() == 0) {
			return;
		}
		if (hasResidualParticles(firstParent) || hasResidualParticles(secondParent)) {
			throw new IllegalArgumentException(
					"generic transforms cannot relabel inherited random mass as database exact");
		}
	}

	private boolean hasResidualParticles(EvidenceStateRef reference) {
		return reference != null
				&& references[validate(reference)].summary().guarantee() != EvidenceGuarantee.DATABASE_EXACT;
	}

	private int payloadStateId(int stateId) {
		int ownerStateId = payloadOwnerStateIds[stateId];
		return ownerStateId == 0 ? stateId : ownerStateId;
	}

	private void redirectPayloadOwner(int priorOwnerStateId, int replacementOwnerStateId) {
		if (priorOwnerStateId == replacementOwnerStateId
				|| payloadOwnerStateIds[replacementOwnerStateId] != replacementOwnerStateId
				|| payloadStatuses[replacementOwnerStateId] != (byte) FrontierPayloadStatus.RESIDENT.ordinal()
				|| payloadBlocks[replacementOwnerStateId] == null) {
			throw new IllegalArgumentException("replacement Frontier payload state must be a resident owner");
		}
		boolean redirected = false;
		for (int stateId = 1; stateId <= highWaterStateId; stateId++) {
			if (payloadOwnerStateIds[stateId] == priorOwnerStateId) {
				payloadOwnerStateIds[stateId] = replacementOwnerStateId;
				redirected = true;
			}
		}
		if (!redirected) {
			throw new IllegalStateException("evicted Frontier payload owner has no referencing states");
		}
	}

	private boolean containsEvidenceKey(int stateId, String evidenceKey) {
		EvidenceCalibrationSummary calibration = calibrations[stateId];
		if (calibration != null && calibration.evidenceKey().equals(evidenceKey)) {
			return true;
		}
		int firstParentStateId = firstParentStateIds[stateId];
		if (firstParentStateId != 0 && containsEvidenceKey(firstParentStateId, evidenceKey)) {
			return true;
		}
		int secondParentStateId = secondParentStateIds[stateId];
		return secondParentStateId != 0 && containsEvidenceKey(secondParentStateId, evidenceKey);
	}

	private EvidenceCalibrationSummary nearestCalibration(int stateId) {
		EvidenceCalibrationSummary calibration = calibrations[stateId];
		if (calibration != null) {
			return calibration;
		}
		int firstParentStateId = firstParentStateIds[stateId];
		if (firstParentStateId != 0) {
			EvidenceCalibrationSummary inherited = nearestCalibration(firstParentStateId);
			if (inherited != null) {
				return inherited;
			}
		}
		int secondParentStateId = secondParentStateIds[stateId];
		return secondParentStateId == 0 ? null : nearestCalibration(secondParentStateId);
	}

	private double cumulativeCalibrationFactor(int stateId) {
		double local = calibrations[stateId] == null ? 1.0d : calibrations[stateId].factor();
		int firstParentStateId = firstParentStateIds[stateId];
		int secondParentStateId = secondParentStateIds[stateId];
		double inherited;
		if (firstParentStateId == 0) {
			inherited = secondParentStateId == 0 ? 1.0d : cumulativeCalibrationFactor(secondParentStateId);
		} else if (secondParentStateId == 0) {
			inherited = cumulativeCalibrationFactor(firstParentStateId);
		} else {
			double first = cumulativeCalibrationFactor(firstParentStateId);
			double second = cumulativeCalibrationFactor(secondParentStateId);
			if (!Double.isFinite(first) || !Double.isFinite(second) || !approximatelyEqual(first, second)) {
				return Double.NaN;
			}
			inherited = first;
		}
		double result = local * inherited;
		return Double.isFinite(result) && result > 0.0d ? result : Double.NaN;
	}

	private static EvidenceCalibrationSummary boundedCalibration(
			EvidenceStateSummary rawSummary,
			EvidenceCalibrationSummary requested) {
		double boundedRows = Math.min(requested.finalRows(), rawSummary.certifiedUpperBound());
		double boundedFactor = requested.rawRows() == 0.0d
				? boundedRows == 0.0d ? 0.0d : Double.POSITIVE_INFINITY
				: boundedRows / requested.rawRows();
		if (Double.doubleToLongBits(boundedRows) == Double.doubleToLongBits(requested.finalRows())
				&& Double.doubleToLongBits(boundedFactor) == Double.doubleToLongBits(requested.factor())) {
			return requested;
		}
		return new EvidenceCalibrationSummary(
				requested.rawRows(),
				boundedRows,
				boundedFactor,
				requested.source(),
				requested.evidenceCount(),
				requested.correctionConfidence(),
				requested.evidenceKey(),
				requested.evidenceRevision());
	}

	private static EvidenceStateSummary calibratedSummary(
			EvidenceStateSummary rawSummary,
			EvidenceCalibrationSummary calibration) {
		double factor = calibration.factor();
		double finalRows = calibration.finalRows();
		double certifiedBound = rawSummary.certifiedUpperBound();
		double lower = Math.min(finalRows, scaleBound(rawSummary.lowerRows(), factor));
		double upper = Math.max(finalRows, Math.min(scaleBound(rawSummary.upperRows(), factor), certifiedBound));
		double varianceFactor = factor * factor;
		return new EvidenceStateSummary(
				finalRows,
				lower,
				upper,
				0.0d,
				EvidenceIntervalKind.HEURISTIC,
				scaleBound(rawSummary.inheritedVariance(), varianceFactor),
				scaleBound(rawSummary.mutationVariance(), varianceFactor),
				scaleBound(rawSummary.resamplingVariance(), varianceFactor),
				rawSummary.effectiveSampleSize(),
				rawSummary.maximumWeightFraction(),
				certifiedBound,
				EvidenceGuarantee.LEARNED_CALIBRATED,
				EvidenceZeroStatus.POSITIVE,
				"");
	}

	private static EvidenceStateSummary summaryOnlyCalibration(
			EvidenceStateSummary rawSummary,
			EvidenceCalibrationSummary calibration,
			String reason) {
		double finalRows = calibration.finalRows();
		double certifiedBound = rawSummary.certifiedUpperBound();
		double intervalUpper = Double.isFinite(certifiedBound)
				? certifiedBound
				: Math.max(finalRows, rawSummary.upperRows());
		if (finalRows == 0.0d) {
			return EvidenceStateSummary.unresolved(finalRows, intervalUpper, certifiedBound, reason);
		}
		return new EvidenceStateSummary(
				finalRows,
				0.0d,
				intervalUpper,
				0.0d,
				EvidenceIntervalKind.HEURISTIC,
				Double.POSITIVE_INFINITY,
				Double.POSITIVE_INFINITY,
				Double.POSITIVE_INFINITY,
				0.0d,
				1.0d,
				certifiedBound,
				EvidenceGuarantee.LEARNED_CALIBRATED,
				EvidenceZeroStatus.POSITIVE,
				reason);
	}

	private static double multiplyScale(double left, double right) {
		double result = left * right;
		if (!Double.isFinite(result) || result <= 0.0d) {
			throw new IllegalArgumentException("cumulative calibration scale must remain finite and positive");
		}
		return result;
	}

	private static double scaleBound(double value, double factor) {
		if (value == 0.0d || factor == 0.0d) {
			return 0.0d;
		}
		double scaled = value * factor;
		return Double.isFinite(scaled) ? scaled : Double.POSITIVE_INFINITY;
	}

	private static boolean sameDiagnostic(double claimed, double derived) {
		if (!Double.isFinite(claimed) || !Double.isFinite(derived)) {
			return false;
		}
		if (Double.doubleToLongBits(claimed) == Double.doubleToLongBits(derived)) {
			return true;
		}
		double scale = Math.max(1.0d, Math.max(Math.abs(claimed), Math.abs(derived)));
		return Math.abs(claimed - derived) <= 8.0d * Math.ulp(scale);
	}

	private static boolean approximatelyEqual(double left, double right) {
		if (Double.doubleToLongBits(left) == Double.doubleToLongBits(right)) {
			return true;
		}
		double scale = Math.max(1.0d, Math.max(Math.abs(left), Math.abs(right)));
		return Math.abs(left - right) <= 8.0d * Math.ulp(scale);
	}

	private int stateId(EvidenceStateRef reference) {
		return reference == null ? 0 : validate(reference);
	}

	private static int sumCounts(int[] counts) {
		Objects.requireNonNull(counts, "counts");
		int sum = 0;
		for (int count : counts) {
			if (count < 0) {
				throw new IllegalArgumentException("particle counts must be nonnegative");
			}
			sum = Math.addExact(sum, count);
		}
		return sum;
	}

	private long totalReservedBytes() {
		return allocatedBytes + residentPayloadBytes + temporaryReservedBytes;
	}

	private void requireAvailableBytes(long bytes, FrontierMemoryPurpose purpose) {
		if (bytes < 0L || bytes == Long.MAX_VALUE || totalReservedBytes() > memoryBudgetBytes - bytes) {
			throw new FrontierMemoryLimitException(bytes, totalReservedBytes(), memoryBudgetBytes, purpose);
		}
	}

	private void updatePeak() {
		peakReservedBytes = Math.max(peakReservedBytes, totalReservedBytes());
	}

	private void ensureCapacity(int requiredStateId) {
		if (requiredStateId < pointRows.length) {
			return;
		}
		int current = pointRows.length;
		int replacement = Math.max(requiredStateId + 1, current + (current >>> 1));
		long replacementBytes = columnsBytes(replacement);
		try (FrontierMemoryReservation resize = reserveTemporary(
				replacementBytes,
				FrontierMemoryPurpose.ARRAY_GROWTH)) {
			double[] replacementPointRows = Arrays.copyOf(pointRows, replacement);
			double[] replacementLowerRows = Arrays.copyOf(lowerRows, replacement);
			double[] replacementUpperRows = Arrays.copyOf(upperRows, replacement);
			double[] replacementConfidence = Arrays.copyOf(confidence, replacement);
			double[] replacementInheritedVariance = Arrays.copyOf(inheritedVariance, replacement);
			double[] replacementMutationVariance = Arrays.copyOf(mutationVariance, replacement);
			double[] replacementResamplingVariance = Arrays.copyOf(resamplingVariance, replacement);
			double[] replacementEffectiveSampleSize = Arrays.copyOf(effectiveSampleSize, replacement);
			double[] replacementMaximumWeightFraction = Arrays.copyOf(maximumWeightFraction, replacement);
			double[] replacementCertifiedUpperBound = Arrays.copyOf(certifiedUpperBound, replacement);
			double[] replacementCumulativeWeightScales = Arrays.copyOf(cumulativeWeightScales, replacement);
			int[] replacementIntervalKinds = Arrays.copyOf(intervalKinds, replacement);
			int[] replacementGuarantees = Arrays.copyOf(guarantees, replacement);
			int[] replacementZeroStatuses = Arrays.copyOf(zeroStatuses, replacement);
			FrontierLayout[] replacementLayouts = Arrays.copyOf(layouts, replacement);
			String[] replacementDegradationReasons = Arrays.copyOf(degradationReasons, replacement);
			FrontierStateKey[] replacementKeys = Arrays.copyOf(keys, replacement);
			long[] replacementDeterministicSeeds = Arrays.copyOf(deterministicSeeds, replacement);
			EvidenceStateRef[] replacementReferences = Arrays.copyOf(references, replacement);
			boolean[] replacementMaterialized = Arrays.copyOf(materialized, replacement);
			byte[] replacementOperations = Arrays.copyOf(operations, replacement);
			byte[] replacementDispositions = Arrays.copyOf(dispositions, replacement);
			int[] replacementFirstParentStateIds = Arrays.copyOf(firstParentStateIds, replacement);
			int[] replacementSecondParentStateIds = Arrays.copyOf(secondParentStateIds, replacement);
			int[] replacementOperationRecipeIds = Arrays.copyOf(operationRecipeIds, replacement);
			int[] replacementPayloadOwnerStateIds = Arrays.copyOf(payloadOwnerStateIds, replacement);
			FrontierPayloadBlock[] replacementPayloadBlocks = Arrays.copyOf(payloadBlocks, replacement);
			EvidenceCalibrationSummary[] replacementCalibrations = Arrays.copyOf(calibrations, replacement);
			byte[] replacementPayloadStatuses = Arrays.copyOf(payloadStatuses, replacement);
			int[] replacementPayloadPinCounts = Arrays.copyOf(payloadPinCounts, replacement);
			int[] replacementExactAtomCounts = Arrays.copyOf(exactAtomCounts, replacement);
			int[] replacementResidualParticleCounts = Arrays.copyOf(residualParticleCounts, replacement);
			long[] replacementPayloadBytesByState = Arrays.copyOf(payloadBytesByState, replacement);
			long[] replacementPayloadDigestHigh = Arrays.copyOf(payloadDigestHigh, replacement);
			long[] replacementPayloadDigestLow = Arrays.copyOf(payloadDigestLow, replacement);

			long currentBytes = columnsBytes(current);
			pointRows = replacementPointRows;
			lowerRows = replacementLowerRows;
			upperRows = replacementUpperRows;
			confidence = replacementConfidence;
			inheritedVariance = replacementInheritedVariance;
			mutationVariance = replacementMutationVariance;
			resamplingVariance = replacementResamplingVariance;
			effectiveSampleSize = replacementEffectiveSampleSize;
			maximumWeightFraction = replacementMaximumWeightFraction;
			certifiedUpperBound = replacementCertifiedUpperBound;
			cumulativeWeightScales = replacementCumulativeWeightScales;
			intervalKinds = replacementIntervalKinds;
			guarantees = replacementGuarantees;
			zeroStatuses = replacementZeroStatuses;
			layouts = replacementLayouts;
			degradationReasons = replacementDegradationReasons;
			keys = replacementKeys;
			deterministicSeeds = replacementDeterministicSeeds;
			references = replacementReferences;
			materialized = replacementMaterialized;
			operations = replacementOperations;
			dispositions = replacementDispositions;
			firstParentStateIds = replacementFirstParentStateIds;
			secondParentStateIds = replacementSecondParentStateIds;
			operationRecipeIds = replacementOperationRecipeIds;
			payloadOwnerStateIds = replacementPayloadOwnerStateIds;
			payloadBlocks = replacementPayloadBlocks;
			calibrations = replacementCalibrations;
			payloadStatuses = replacementPayloadStatuses;
			payloadPinCounts = replacementPayloadPinCounts;
			exactAtomCounts = replacementExactAtomCounts;
			residualParticleCounts = replacementResidualParticleCounts;
			payloadBytesByState = replacementPayloadBytesByState;
			payloadDigestHigh = replacementPayloadDigestHigh;
			payloadDigestLow = replacementPayloadDigestLow;
			resize.transferToMetadata(replacementBytes);
			allocatedBytes -= currentBytes;
		}
	}

	private void allocate(int capacity) {
		pointRows = new double[capacity];
		lowerRows = new double[capacity];
		upperRows = new double[capacity];
		confidence = new double[capacity];
		inheritedVariance = new double[capacity];
		mutationVariance = new double[capacity];
		resamplingVariance = new double[capacity];
		effectiveSampleSize = new double[capacity];
		maximumWeightFraction = new double[capacity];
		certifiedUpperBound = new double[capacity];
		cumulativeWeightScales = new double[capacity];
		intervalKinds = new int[capacity];
		guarantees = new int[capacity];
		zeroStatuses = new int[capacity];
		layouts = new FrontierLayout[capacity];
		degradationReasons = new String[capacity];
		keys = new FrontierStateKey[capacity];
		deterministicSeeds = new long[capacity];
		references = new EvidenceStateRef[capacity];
		materialized = new boolean[capacity];
		operations = new byte[capacity];
		dispositions = new byte[capacity];
		firstParentStateIds = new int[capacity];
		secondParentStateIds = new int[capacity];
		operationRecipeIds = new int[capacity];
		payloadOwnerStateIds = new int[capacity];
		payloadBlocks = new FrontierPayloadBlock[capacity];
		calibrations = new EvidenceCalibrationSummary[capacity];
		payloadStatuses = new byte[capacity];
		payloadPinCounts = new int[capacity];
		exactAtomCounts = new int[capacity];
		residualParticleCounts = new int[capacity];
		payloadBytesByState = new long[capacity];
		payloadDigestHigh = new long[capacity];
		payloadDigestLow = new long[capacity];
	}

	private void ensureCanonicalCapacity(int required) {
		if (required * 10L < canonicalSlots.length * 6L) {
			return;
		}
		int replacementLength = canonicalSlots.length;
		do {
			replacementLength = Math.multiplyExact(replacementLength, 2);
		} while (required * 10L >= replacementLength * 6L);
		long replacementBytes = arrayBytes(replacementLength, Integer.BYTES);
		try (FrontierMemoryReservation resize = reserveTemporary(
				replacementBytes,
				FrontierMemoryPurpose.ARRAY_GROWTH)) {
			int[] replacement = new int[replacementLength];
			for (int stateId : canonicalSlots) {
				if (stateId != 0) {
					int slot = canonicalSlot(keys[stateId], replacement);
					replacement[slot] = stateId;
				}
			}
			long currentBytes = arrayBytes(canonicalSlots.length, Integer.BYTES);
			canonicalSlots = replacement;
			resize.transferToMetadata(replacementBytes);
			allocatedBytes -= currentBytes;
		}
	}

